import { useEffect, useState } from "react";

import "./Users.css";

function Users() {
  const [user, setUser] = useState([]);

  useEffect(() => {
    function getData() {
      fetch("https://673b986796b8dcd5f3f6e23a.mockapi.io/dataForReact")
        .then((res) => res.json())
        .then((res) => setUser(res));
    }
    getData();
  }, []);

  let title = [
    "ID",
    "Photo",
    "Name",
    "Age",
    "Password <eye-fill/>",
    "Created Date",
    "Delete Button",
  ];

  return (
    <div className="mainDivUsers">
      <div className="heading">
        {title.map((elm) => {
          return <p className="headingp">{elm}</p>;
        })}
      </div>
      <div className="userData">
        {user.map((elm, index) => {
          return (
            <div className="userBox" key={index}>
              <p>{elm.id}</p>
              <img src={elm.avatar} alt="" />
              <p>{elm.name}</p>
              <p>{elm.age}</p>
              .
              <p>{elm.createdAt}</p>
              <button
                className="deleteBtn"
                style={{ backgroundColor: elm.color }}
              >
                Delete
              </button>
            </div>
          );
        })}
      </div>
    </div>
  );
}

export default Users;
